package com.glassbox.chess; import com.glassbox.chess.domain.*; import com.glassbox.chess.rule.Perft; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; public class PerftTest{@Test void standardStartPositionPerft(){Board b=new Board();b.setupInitialPosition();assertEquals(20,Perft.explore(b,1));assertEquals(400,Perft.explore(b,2));assertEquals(8902,Perft.explore(b,3));long start=System.nanoTime();assertEquals(197281,Perft.explore(b,4));assertTrue((System.nanoTime()-start)/1_000_000<2000,"Perft(4) exceeded 2 seconds");}}
